import {
    Table,
    DateTimeColumn,
    BooleanColumn,
    DurationColumn,
    ReferenceColumn,
    GuidColumn,
    GenericColumn,
    NameValuePairsColumn,
    StringColumn,
    IntegerColumn,
    DomainPathColumn,
    DocumentIdColumn,
    DomainIdColumn,
} from '@servicenow/sdk/core'

export const wf_context = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        scope_master: 'workflow',
    },
    label: 'Workflow context',
    name: 'wf_context',
    schema: {
        ended: DateTimeColumn({
            label: [
                {
                    hint: 'Absolute time the workflow completed',
                    label: 'Ended',
                    plural: 'Ended',
                    language: 'en',
                },
            ],
        }),
        after_business_rules: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Defer running of the workflow until all before and after business rules have completed',
                    label: 'Run after bus. rules run',
                    plural: 'Run after bus. rules runs',
                    language: 'en',
                },
            ],
        }),
        running_duration: DurationColumn({
            label: [
                {
                    hint: 'Duration for which context was running',
                    label: 'Running duration',
                    plural: 'Running durations',
                    language: 'en',
                },
            ],
            maxLength: 40,
        }),
        parent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    label: 'Parent Workflow',
                    plural: 'Parent Workflows',
                    language: 'en',
                },
            ],
            readOnly: true,
            referenceTable: 'wf_context',
        }),
        stage: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'clear',
            label: [
                {
                    hint: 'Current Workflow Stage',
                    label: 'Stage',
                    plural: 'Stages',
                    language: 'en',
                },
            ],
            referenceTable: 'wf_stage',
            referenceQual: "javascript:'workflow_version=' + current.workflow_version;",
        }),
        auto_start: BooleanColumn({
            label: 'Auto start',
        }),
        cumulated_avg_ert: BooleanColumn({
            label: [
                {
                    hint: 'Cumulated average estimated run time',
                    label: 'Cumulative to ERT',
                    plural: 'Cumulative to ERTs',
                    language: 'en',
                },
            ],
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        table: GenericColumn({
            columnType: 'short_table_name',
            label: [
                {
                    hint: 'Table the related record belongs to',
                    label: 'Table',
                    plural: 'Tables',
                    language: 'en',
                },
            ],
            readOnly: true,
            tableReference: true,
        }),
        scratchpad: NameValuePairsColumn({
            label: [
                {
                    hint: 'A json object containing all shared data between activities',
                    label: 'Scratchpad',
                    plural: 'Scratchpads',
                    language: 'en',
                },
            ],
            maxLength: 8000,
            readOnly: true,
        }),
        schedule: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Schedule',
                    label: 'Schedule',
                    plural: 'Schedules',
                    language: 'en',
                },
            ],
            referenceTable: 'cmn_schedule',
        }),
        without_current_wf_actions: GenericColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            columnType: 'glide_action_list',
            default: '51782761ac1464174baaeb9af4b9ae76,b69c7e18eb532100ec9a82810206fea4',
            label: 'Available actions',
            maxLength: 1024,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        state: StringColumn({
            default: 'executing',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Workflow execution state',
                    label: 'State',
                    plural: 'States',
                    language: 'en',
                },
            ],
        }),
        activity_count: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Loop detection and prevention',
                    label: 'Activity count',
                    plural: 'Activity counts',
                    language: 'en',
                },
            ],
        }),
        stage_state: StringColumn({
            label: [
                {
                    label: 'Stage states',
                    plural: 'Stage stages',
                    language: 'en',
                },
            ],
            maxLength: 8000,
            readOnly: true,
        }),
        ert_outlier_workflow_actions: GenericColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            columnType: 'glide_action_list',
            default: 'b69c7e18eb532100ec9a82810206fea4',
            label: 'Available actions',
            maxLength: 1024,
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        workflow_version: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Parent workflow version',
                    label: 'Workflow version',
                    plural: 'Workflow versions',
                    language: 'en',
                },
            ],
            readOnly: true,
            referenceTable: 'wf_workflow_version',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        id: DocumentIdColumn({
            dependent: 'table',
            label: [
                {
                    hint: 'The record the workflow instance is being executed on',
                    label: 'Related record',
                    plural: 'Related records',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Active means have not reached a terminal state',
                    label: 'Active',
                    plural: 'Active',
                    language: 'en',
                },
            ],
        }),
        timezone: StringColumn({
            dropdown: 'dropdown_with_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sys_user',
                field: 'time_zone',
            },
            label: [
                {
                    hint: 'Timezone override',
                    label: 'Timezone',
                    plural: 'Timezones',
                    language: 'en',
                },
            ],
        }),
        ert_long_running_actions: GenericColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            columnType: 'glide_action_list',
            default:
                '51782761ac1464174baaeb9af4b9ae76,803b3c728f320100ec9a6441f0f923ef,b69c7e18eb532100ec9a82810206fea4',
            label: 'Available actions',
            maxLength: 1024,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        started: DateTimeColumn({
            label: [
                {
                    hint: 'Absolute time the workflow began',
                    label: 'Started',
                    plural: 'Started',
                    language: 'en',
                },
            ],
        }),
        activity_index: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Index assigned to activities as they are transitioned to in the process of workflow execution',
                    label: 'Activity index',
                    plural: 'Activity indexes',
                    language: 'en',
                },
            ],
        }),
        column_renderer: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Type of display for stages',
                    label: 'Stage rendering',
                    plural: 'Stage renderings',
                    language: 'en',
                },
            ],
            referenceTable: 'column_renderer',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        due: DateTimeColumn({
            label: [
                {
                    hint: 'Estimated Completion Date',
                    label: 'Due',
                    plural: 'Dues',
                    language: 'en',
                },
            ],
        }),
        started_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'none',
            label: [
                {
                    hint: 'User that initiated this instance of workflow execution(if any)',
                    label: 'Started by',
                    plural: 'Started by',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        requires_ert: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Requires an estimated run time',
                    label: 'Requires ERT',
                    plural: 'Requires ERTs',
                    language: 'en',
                },
            ],
        }),
        parent_activity: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Parent activity',
            readOnly: true,
            referenceTable: 'wf_executing',
        }),
        result: StringColumn({
            label: [
                {
                    hint: 'May be (manually) set by workflow activity to indicate overall result',
                    label: 'Result',
                    plural: 'Results',
                    language: 'en',
                },
            ],
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the workflow belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        return_value: NameValuePairsColumn({
            label: [
                {
                    hint: 'Has a return value to the parent workflow',
                    label: 'Return value',
                    plural: 'Return values',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        name: StringColumn({
            label: [
                {
                    hint: 'Copied from workflow to make messages readable',
                    label: 'Name',
                    plural: 'Names',
                    language: 'en',
                },
            ],
            maxLength: 100,
            readOnly: true,
        }),
        workflow: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Workflow',
            referenceTable: 'wf_workflow',
        }),
    },
})
